            {
              "type": "text",
              "content": "Investors cannot know the future with certainty. Instead, they consider possible outcomes, the likelihood of those outcomes, and whether the potential reward justifies the risk."
            },
            {
              "type": "example",
              "title": "Thinking in possibilities",
              "content": "Suppose an investment could produce a strong return, a small return, or a significant loss. A thoughtful investor does not focus only on the strongest outcome. They consider all three possibilities."
            },
            {
              "type": "heading",
              "content": "Investor versus speculator"
            },
            {
              "type": "text",
              "content": "Investing and speculation can overlap, but they are not identical. An investor generally evaluates an asset's potential value, risks, and role in a financial plan. A speculator may place greater emphasis on expected price movements and short-term opportunities."
            },
            {
              "type": "callout",
              "title": "Neither word automatically means good or bad",
              "content": "The important question is whether the person understands what they are doing, the risks involved, and whether the decision fits their financial situation."
            },
            {
              "type": "heading",
              "content": "Step 1: Define the goal"
            },
            {
              "type": "text",
              "content": "Every investment decision should begin with a purpose. Your goal might be retirement, long-term wealth building, future education costs, buying a home, generating income, or another objective."
            },
            {
              "type": "example",
              "title": "Different goals, different decisions",
              "content": "Someone saving for a payment due in three months has a very different problem from someone investing for retirement in 25 years. Treating the two situations identically would ignore an important part of the decision."
            },
            {
              "type": "heading",
              "content": "Step 2: Identify the time horizon"
            },
            {
              "type": "text",
              "content": "Time horizon is the amount of time before you expect to need the money. It influences how much short-term volatility you may be able to tolerate and how much opportunity you have for long-term growth."
            },
            {
              "type": "heading",
              "content": "Step 3: Understand your risk"
            },
            {
              "type": "text",
              "content": "Ask what could go wrong. Could the investment fall sharply? Could the income stop? Could the investment become difficult to sell? Could the underlying business fail? Understanding possible losses is just as important as thinking about possible gains."
            },
            {
              "type": "heading",
              "content": "Step 4: Understand what you own"
            },
            {
              "type": "text",
              "content": "Never invest in something simply because its name sounds familiar. Understand what the investment represents, what produces its potential return, what risks affect it, and what could cause its value to decline."
            },
            {
              "type": "example",
              "title": "Ask what creates the return",
              "content": "If someone offers you an investment promising attractive returns, ask: Where does the money come from? What asset or activity generates the return? What happens if that activity performs poorly?"
            },
            {
              "type": "heading",
              "content": "Step 5: Examine the expected return"
            },
            {
              "type": "text",
              "content": "Expected return is not the same as guaranteed return. Investors should understand whether a stated number is a historical result, an estimate, a target, or a contractual payment."
            },
            {
              "type": "callout",
              "title": "Words matter",
              "content": "Past return, projected return, target return, and guaranteed return do not mean the same thing."
            },
            {
              "type": "heading",
              "content": "Step 6: Look at fees"
            },
            {
              "type": "text",
              "content": "Fees reduce the money that remains for the investor. A fee that looks small may become meaningful over many years, especially when the money could otherwise have remained invested and compounded."
            },
            {
              "type": "example",
              "title": "A simple fee example",
              "content": "Suppose an investment account has $10,000 and charges an annual fee of 1%. Ignoring changes in value, approximately $100 would be charged for that year."
            },
            {
              "type": "formula",
              "content": "$10,000 × 1% = $100"
            },
            {
              "type": "heading",
              "content": "Fees can compound too"
            },
            {
              "type": "text",
              "content": "Fees do not only reduce the amount you pay today. Money used to pay fees is money that is no longer available to potentially earn future returns."
            },
            {
              "type": "heading",
              "content": "Step 7: Consider taxes"
            },
            {
              "type": "text",
              "content": "Depending on the country, investment income and gains may have tax consequences. A return shown before taxes is not necessarily the amount the investor ultimately keeps."
            },
            {
              "type": "heading",
              "content": "Step 8: Consider liquidity"
            },
            {
              "type": "text",
              "content": "Liquidity describes how easily an investment can be converted into cash without accepting an unreasonable price. An investment can be attractive but still unsuitable if you need immediate access to the money."
            },
            {
              "type": "example",
              "title": "Liquidity matters",
              "content": "Imagine you need $3,000 next month. An investment that might take a long time to sell or could require a large price reduction to sell quickly may be a poor match for that goal."
            },
            {
              "type": "heading",
              "content": "Step 9: Think about diversification"
            },
            {
              "type": "text",
              "content": "A thoughtful investor considers whether too much of the portfolio depends on one company, industry, country, asset type, or other source of risk."
            },
            {
              "type": "heading",
              "content": "Step 10: Check the evidence"
            },
            {
              "type": "text",
              "content": "Investment decisions should be based on reliable information rather than excitement, rumors, social-media hype, or pressure from other people."
            },
            {
              "type": "heading",
              "content": "Beware of FOMO"
            },
            {
              "type": "text",
              "content": "FOMO means fear of missing out. It can cause investors to buy something simply because its price has recently risen or because everyone around them appears to be making money."
            },
            {
              "type": "example",
              "title": "A FOMO decision",
              "content": "Imagine an asset rises rapidly and your friends tell you that you are missing your chance. Buying immediately without understanding the asset, its valuation, its risks, or your own goal is an emotional decision rather than a well-researched investment decision."
            },
            {
              "type": "heading",
              "content": "Avoid panic selling"
            },
            {
              "type": "text",
              "content": "The opposite emotional mistake is selling purely because prices have fallen. A decline can be frightening, but investors should distinguish between a temporary market movement and a fundamental change in the reason they owned the investment."
            },
            {
              "type": "heading",
              "content": "Do not confuse price with value"
            },
            {
              "type": "text",
              "content": "A low-priced investment is not automatically cheap, and a high-priced investment is not automatically expensive. The price must be considered alongside what the investor is actually receiving for that price."
            },
            {
              "type": "example",
              "title": "Cheap does not always mean good value",
              "content": "A company whose shares have fallen from $50 to $10 may look cheap. But if the company's underlying business has deteriorated severely, the lower price may reflect that deterioration rather than create an attractive opportunity."
            },
            {
              "type": "heading",
              "content": "Watch for unrealistic promises"
            },
            {
              "type": "text",
              "content": "Claims of extremely high returns with little or no risk deserve serious skepticism. Investors should ask how the return is generated and whether the claim can be independently verified."
            },
            {
              "type": "callout",
              "title": "Red flag",
              "content": "Guaranteed high returns, urgent pressure to invest, secret strategies, requests to recruit others, or instructions to send money without proper documentation should all trigger caution."
            },
            {
              "type": "heading",
              "content": "Do not invest in what you do not understand"
            },
            {
              "type": "text",
              "content": "Complexity does not automatically make an investment better. If you cannot explain in simple language what you are buying, how it can make money, and what could cause you to lose money, you may need to learn more before investing."
            },
            {
              "type": "heading",
              "content": "The investor decision sequence"
            },
            {
              "type": "text",
              "content": "A useful sequence is: Goal → Time horizon → Risk capacity and tolerance → Investment options → Research → Costs → Diversification → Decision → Review."
            },
            {
              "type": "heading",
              "content": "A practical decision example"
            },
            {
              "type": "example",
              "title": "Choosing between two investments",
              "content": "You have $15,000 for a long-term goal. Investment A has lower expected volatility but a lower potential return. Investment B has higher potential return but could experience much larger declines. The right choice depends on your goal, time horizon, ability to handle losses, diversification, costs, and the details of the investments—not simply which number is larger."
            },
            {
              "type": "heading",
              "content": "Reviewing an investment after buying it"
            },
            {
              "type": "text",
              "content": "Thinking like an investor does not end after buying. Periodically review whether the investment still serves its intended purpose, whether your circumstances have changed, whether the risk remains appropriate, and whether the original reasons for owning it still make sense."
            },
            {
              "type": "heading",
              "content": "Do not constantly trade just to feel active"
            },
            {
              "type": "text",
              "content": "Frequent buying and selling can increase costs, taxes, and emotional decision-making. Activity is not the same thing as good investing."
            },
            {
              "type": "heading",
              "content": "Common misconceptions"
            },
            {
              "type": "heading",
              "content": "Misconception: A good investor always knows what will happen next"
            },
            {
              "type": "text",
              "content": "Reality: No investor can reliably predict every future market movement. Good investing involves managing uncertainty rather than eliminating it."
            },
            {
              "type": "heading",
              "content": "Misconception: The most expensive investment is automatically the best"
            },
            {
              "type": "text",
              "content": "Reality: Price alone does not tell you whether an investment is good value."
            },
            {
              "type": "heading",
              "content": "Misconception: More trading means better investing"
            },
            {
              "type": "text",
              "content": "Reality: Frequent activity can increase costs and emotional mistakes. A good decision does not become better simply because it is repeated often."
            },
            {
              "type": "heading",
              "content": "Misconception: A recommendation from a friend is enough research"
            },
            {
              "type": "text",
              "content": "Reality: You are responsible for understanding an investment before putting your money into it."
            },
            {
              "type": "heading",
              "content": "Misconception: If an investment has risen recently, it must keep rising"
            },
            {
              "type": "text",
              "content": "Reality: Recent performance does not guarantee future performance."
            },
            {
              "type": "heading",
              "content": "Misconception: You need to understand everything about finance before investing"
            },
            {
              "type": "text",
              "content": "Reality: You do not need to know every financial concept before starting to learn about investing. But you should understand the investment you are considering, its major risks, costs, and purpose."
            },
            {
              "type": "heading",
              "content": "Practical investor checklist"
            },
            {
              "type": "interactive",
              "title": "Before you invest",
              "content": "Ask yourself: What is my goal? When will I need the money? What exactly am I buying? How can it generate a return? What can make me lose money? How much could I lose? What are the fees? What are the tax implications? How easily can I sell? Is my portfolio diversified? Am I making this decision because of evidence or emotion?"
            },
            {
              "type": "summary",
              "content": "Thinking like an investor means making decisions deliberately rather than emotionally. Start with the goal, understand the time horizon and risk, learn what you own, evaluate potential returns, examine fees and taxes, consider liquidity and diversification, verify information, and avoid decisions driven by FOMO or panic."
            },
            {
              "type": "callout",
              "title": "Remember",
              "content": "A strong investor is not someone who never makes a mistake. It is someone who learns to make decisions based on goals, evidence, risk, costs, and long-term thinking."
            }
