            {
              "type": "interactive",
              "title": "Before you buy",
              "content": "Write a short answer to each question: What am I buying? How does it produce a potential return? What am I paying? What are the major risks? What evidence supports my expectations? What could make my analysis wrong? How does this investment fit my goal and existing portfolio?"
            },
            {
              "type": "heading",
              "content": "When you should pause"
            },
            {
              "type": "text",
              "content": "Pause when you cannot explain how the investment works, when the promised return sounds unusually certain, when you feel pressured to act immediately, when you do not understand the fees, when you are relying mainly on someone else's recommendation, or when the potential loss would seriously damage your finances."
            },
            {
              "type": "heading",
              "content": "Evaluation is not prediction"
            },
            {
              "type": "text",
              "content": "Even a careful analysis can be wrong. Businesses can change, economies can surprise investors, markets can behave unexpectedly, and assumptions can fail. Good evaluation does not create certainty. It improves the quality of the decision under uncertainty."
            },
            {
              "type": "heading",
              "content": "The bigger lesson"
            },
            {
              "type": "text",
              "content": "The goal of evaluating an investment is not to find something that can never lose value. The goal is to understand the opportunity well enough to decide whether the potential return, risks, price, costs, and role in your portfolio make sense."
            },
            {
              "type": "summary",
              "content": "Before buying an investment, understand what you are buying, how it can produce a return, what you are paying, what could make it gain or lose value, what assumptions your decision depends on, and what evidence supports those assumptions. Compare alternatives, consider liquidity and concentration, and make sure the investment fits your goal and ability to withstand losses. Good evaluation does not predict the future perfectly; it helps you make better decisions under uncertainty."
            },
            {
              "type": "callout",
              "title": "Remember",
              "content": "Do not ask only, 'How much could I make?' Ask, 'What am I buying, what am I paying, what could go wrong, and what would make this investment no longer make sense?'"
            }
