            {
              "type": "heading",
              "content": "Create rules before emotions become intense"
            },
            {
              "type": "text",
              "content": "One way to reduce emotional decision-making is to establish rules before markets become stressful. Your plan can define how much risk you will take, how diversified you want to be, when you will review investments, and what circumstances would cause you to reconsider an investment."
            },
            {
              "type": "heading",
              "content": "Use a written investment thesis"
            },
            {
              "type": "text",
              "content": "Before making a significant investment, write down why you are buying it, what you expect to happen, what could prove you wrong, and what risks concern you. This creates a reference point that can be reviewed later instead of relying entirely on memory."
            },
            {
              "type": "interactive",
              "title": "Write your reason before you invest",
              "content": "Complete these statements: I am buying this because... I expect... The biggest risk is... I would reconsider if... I expect to hold it for... This investment represents approximately... of my portfolio."
            },
            {
              "type": "heading",
              "content": "Separate information from emotion"
            },
            {
              "type": "text",
              "content": "When a price moves sharply, first identify what actually changed. Then identify how you feel about the change. Separating the facts from the emotional reaction can create space for better reasoning."
            },
            {
              "type": "heading",
              "content": "Slow down important decisions"
            },
            {
              "type": "text",
              "content": "Urgency can make people accept weaker reasoning. When possible, give yourself time to investigate major investment decisions rather than acting immediately because of fear, excitement, or social pressure."
            },
            {
              "type": "heading",
              "content": "Use checklists"
            },
            {
              "type": "text",
              "content": "A checklist can reduce the chance that emotion causes you to skip important questions. Before investing, check the goal, time horizon, risks, valuation, fees, liquidity, diversification, and downside."
            },
            {
              "type": "heading",
              "content": "Understand that you cannot control the market"
            },
            {
              "type": "text",
              "content": "Investors cannot control market prices or guarantee outcomes. What they can control includes how much they invest, what they buy, how diversified they are, how much risk they take, their costs, and how they respond to uncertainty."
            },
            {
              "type": "heading",
              "content": "The goal is not to remove emotion"
            },
            {
              "type": "text",
              "content": "Fear and excitement are normal human responses. The goal is not to become emotionless. The goal is to prevent temporary emotions from repeatedly overriding a sensible long-term plan."
            },
            {
              "type": "heading",
              "content": "Common misconceptions"
            },
            {
              "type": "heading",
              "content": "Misconception: Smart investors do not make emotional mistakes"
            },
            {
              "type": "text",
              "content": "Reality: Intelligence does not make someone immune to fear, overconfidence, FOMO, confirmation bias, or other decision-making traps."
            },
            {
              "type": "heading",
              "content": "Misconception: Following the crowd is safer"
            },
            {
              "type": "text",
              "content": "Reality: A large number of investors can be wrong at the same time. Popularity does not eliminate risk."
            },
            {
              "type": "heading",
              "content": "Misconception: A profitable decision was automatically a good decision"
            },
            {
              "type": "text",
              "content": "Reality: A poor decision can sometimes produce a lucky profit. Evaluate the quality of the reasoning and process, not only the result."
            },
            {
              "type": "heading",
              "content": "Misconception: The best way to control emotions is to ignore them"
            },
            {
              "type": "text",
              "content": "Reality: Recognizing emotions can help you understand when they may be influencing your decisions."
            },
            {
              "type": "heading",
              "content": "A practical psychology checklist"
            },
            {
              "type": "interactive",
              "title": "Before making an emotional investment decision",
              "content": "Ask: Am I afraid? Am I excited? Am I buying because other people are buying? Am I trying to recover a previous loss? Am I focusing only on information that supports my opinion? Am I assuming recent performance will continue? Am I overconfident? Has anything fundamental actually changed?"
            },
            {
              "type": "heading",
              "content": "Putting it all together"
            },
            {
              "type": "text",
              "content": "Good investing requires more than knowing financial concepts. It requires managing yourself when prices move, information changes, and uncertainty increases. Understanding your own psychological tendencies can help you recognize when a decision is being driven by a useful change in information and when it is being driven mainly by emotion."
            },
            {
              "type": "summary",
              "content": "Investor psychology explains why people can make poor investment decisions even when they understand the basics. Fear can cause panic selling, excitement can encourage excessive risk, FOMO can create impulsive buying, overconfidence can lead to oversized bets, and biases can distort how information is interpreted. Written plans, checklists, diversification, position limits, and slowing down important decisions can help investors make more deliberate choices."
            },
            {
              "type": "callout",
              "title": "Remember",
              "content": "You cannot control every market movement, but you can control how you prepare for uncertainty and how you respond to it."
            }
