              "content": "A stock rises from $30 to $90. You bought it at $50. You become confident because it has performed well, assume $90 will eventually become $150, and refuse to sell even when the company's outlook weakens because you do not want to admit that your expectations were wrong. Overconfidence, anchoring, and loss aversion can all influence the decision."
