            {
              "type": "heading",
              "content": "Create a cooling-off rule"
            },
            {
              "type": "text",
              "content": "For decisions that are driven by excitement, fear, or social pressure, a short pause can create space for better thinking. The purpose is not to delay every investment decision, but to prevent strong emotions from creating unnecessary urgency."
            },
            {
              "type": "heading",
              "content": "Review decisions, not just results"
            },
            {
              "type": "text",
              "content": "After an investment decision, ask whether your reasoning was sound and whether you followed your process. A loss does not automatically mean the decision was bad, and a gain does not automatically mean the decision was good."
            },
            {
              "type": "heading",
              "content": "Know what you can and cannot control"
            },
            {
              "type": "text",
              "content": "You cannot control market prices, economic events, company announcements, or what other investors do. You can control how much risk you take, how diversified you are, how you evaluate information, and whether you follow your investment process."
            },
            {
              "type": "heading",
              "content": "Common misconceptions"
            },
            {
              "type": "heading",
              "content": "Misconception: Confidence means you should invest more"
            },
            {
              "type": "text",
              "content": "Reality: Confidence does not remove uncertainty. Position size should reflect the overall risk of the investment and portfolio."
            },
            {
              "type": "heading",
              "content": "Misconception: A loss is proof that the original decision was stupid"
            },
            {
              "type": "text",
              "content": "Reality: Uncertain investments can produce losses even when the original reasoning was sensible. Review the process and evidence rather than judging only the outcome."
            },
            {
              "type": "heading",
              "content": "Misconception: A stock below its old price is automatically cheap"
            },
            {
              "type": "text",
              "content": "Reality: The old price is only a reference point. Current value depends on the investment's present and expected future conditions."
            },
            {
              "type": "heading",
              "content": "Misconception: Recent performance tells you exactly what happens next"
            },
            {
              "type": "text",
              "content": "Reality: Recent performance is one piece of information, not a guarantee of future results."
            },
            {
              "type": "heading",
              "content": "The bigger lesson"
            },
            {
              "type": "text",
              "content": "Investing requires dealing with uncertainty while recognizing that your own thinking can introduce additional problems. Overconfidence can increase risk, loss aversion can keep you attached to poor decisions, anchoring can distort how you view prices, and recency can make recent events seem more predictive than they really are."
            },
            {
              "type": "summary",
              "content": "Investors can be influenced by overconfidence, loss aversion, anchoring, recency bias, and other decision-making traps. These patterns can cause excessive concentration, attachment to losing investments, misleading comparisons with old prices, and overreactions to recent events. Written investment reasons, sensible position sizes, deliberate reviews, and pre-decision checklists can help investors make more consistent decisions."
            },
            {
              "type": "callout",
              "title": "Remember",
              "content": "A disciplined investor does not try to predict every market move. The goal is to build a decision process that still works when confidence, fear, excitement, or regret becomes strong."
            }
